import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";import"./chunks/assets.B8sWdo1g.js";var i=JSON.parse(`{"title":"システムアーキテクチャ設計","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 3 プロセス分離モデル","slug":"_1-3-プロセス分離モデル","link":"#_1-3-プロセス分離モデル","children":[{"level":3,"title":"1. バックグラウンドインデックスサービス（Lertaro.Service.exe）","slug":"_1-バックグラウンドインデックスサービス-lertaro-service-exe","link":"#_1-バックグラウンドインデックスサービス-lertaro-service-exe","children":[]},{"level":3,"title":"2. ユーザー UI メインプロセス（Lertaro.App）","slug":"_2-ユーザー-ui-メインプロセス-lertaro-app","link":"#_2-ユーザー-ui-メインプロセス-lertaro-app","children":[]},{"level":3,"title":"3. キーボードフック・ウィンドウ統合プロセス（Lertaro.Service --hook）","slug":"_3-キーボードフック・ウィンドウ統合プロセス-lertaro-service-hook","link":"#_3-キーボードフック・ウィンドウ統合プロセス-lertaro-service-hook","children":[]}]},{"level":2,"title":"2. 共通コアライブラリ（Lertaro.Core）","slug":"_2-共通コアライブラリ-lertaro-core","link":"#_2-共通コアライブラリ-lertaro-core","children":[]},{"level":2,"title":"3. プラグインシステムのアーキテクチャ上の位置づけ","slug":"_3-プラグインシステムのアーキテクチャ上の位置づけ","link":"#_3-プラグインシステムのアーキテクチャ上の位置づけ","children":[]}],"relativePath":"ja-JP/dev-guide/architecture.md","filePath":"ja-JP/dev-guide/architecture.md","lastUpdated":1791112464000}`),a={name:`ja-JP/dev-guide/architecture.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="システムアーキテクチャ設計" tabindex="-1">システムアーキテクチャ設計 <a class="header-anchor" href="#システムアーキテクチャ設計" aria-label="Permalink to “システムアーキテクチャ設計”">​</a></h1><p>Lertaro は、ミリ秒単位の検索とデスクトップ統合を実現しつつ、システム安定性とセキュリティを確保するために、疎結合なマルチプロセス分離モデルを採用しています。</p><p><img src="/architecture.svg" alt="Lertaro アーキテクチャ図" width="840" height="310"></p><h2 id="_1-3-プロセス分離モデル" tabindex="-1">1. 3 プロセス分離モデル <a class="header-anchor" href="#_1-3-プロセス分離モデル" aria-label="Permalink to “1. 3 プロセス分離モデル”">​</a></h2><p>単一コンポーネントの不具合によるシステム全体のクラッシュを防ぎ、管理者権限の範囲を最小限に抑えるため、Lertaro の実行環境は 3 つのプロセスに明確に分離されています。</p><h3 id="_1-バックグラウンドインデックスサービス-lertaro-service-exe" tabindex="-1">1. バックグラウンドインデックスサービス（<code>Lertaro.Service.exe</code>） <a class="header-anchor" href="#_1-バックグラウンドインデックスサービス-lertaro-service-exe" aria-label="Permalink to “1. バックグラウンドインデックスサービス（Lertaro.Service.exe）”">​</a></h3><ul><li><strong>実行権限</strong>：Windows システムの <code>LocalSystem</code> 権限で常駐する Windows サービス。</li><li><strong>担当範囲</strong>：全ドライブのインデックス作成と変更監視を担当。NTFS / ReFS ドライブの USN 変更ジャーナルおよび $MFT を直接読み取り、FAT32 / exFAT の変更イベントを監視し、SMB / NAS 共有を定期的にキャッシュします。</li><li><strong>セキュリティと性能</strong>：SYSTEM 権限で実行されるため UAC プロンプトなしで低レベルのボリュームメタデータに直接アクセスでき、高速な名前付きパイプを通じて結果をユーザープロセスの App に返します。UI プロセスに不要な管理者権限を持たせない安全な設計です。</li></ul><h3 id="_2-ユーザー-ui-メインプロセス-lertaro-app" tabindex="-1">2. ユーザー UI メインプロセス（<code>Lertaro.App</code>） <a class="header-anchor" href="#_2-ユーザー-ui-メインプロセス-lertaro-app" aria-label="Permalink to “2. ユーザー UI メインプロセス（Lertaro.App）”">​</a></h3><ul><li><strong>実行権限</strong>：標準ユーザー権限で動作するセッション分離された WPF デスクトップアプリ。</li><li><strong>担当範囲</strong>：クイック検索ウィンドウ、メイン検索ウィンドウ、設定画面、グローバルホットキー処理、アクションメニュー（<code>Ctrl+O</code>）、QuickLook プレビューを担当。</li><li><strong>IPC と CLI 共有</strong>：双方向の名前付きパイプ <code>LertaroPipe</code> を介してバックグラウンドサービスと通信します（<code>Core.Services.Search.SearchService</code> は App 側のクライアントです）。また、ユーザーごとの名前付きパイプ（<code>AppSearchPipeService</code>）をホストしており、<code>lff</code> コマンドラインツールが App の構築済みメモリテーブルやプラグインを再初期化なしで共有利用できます。</li></ul><h3 id="_3-キーボードフック・ウィンドウ統合プロセス-lertaro-service-hook" tabindex="-1">3. キーボードフック・ウィンドウ統合プロセス（<code>Lertaro.Service --hook</code>） <a class="header-anchor" href="#_3-キーボードフック・ウィンドウ統合プロセス-lertaro-service-hook" aria-label="Permalink to “3. キーボードフック・ウィンドウ統合プロセス（Lertaro.Service --hook）”">​</a></h3><ul><li><strong>実行権限</strong>：バックグラウンドサービスによって起動される専用のヘルパープロセス。サインインしているアカウントが実際の管理者である<strong>場合にのみ昇格して起動</strong>され、それ以外の場合はユーザー自身のトークンで動作します。したがって、後述の回避が使えるのはそうしたマシン上だけになります。</li><li><strong>担当範囲</strong>：低レベルキーボードフックおよびマウス監視を担当。</li><li><strong>UIPI の回避と耐障害性</strong>：Windows の UIPI（ユーザーインターフェイス特権の分離）により、低権限プロセスから管理者権限で実行中のウィンドウへメッセージを送信することは制限されています。この Hook プロセス上でウィンドウアダプター（<a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>, <code>IFileDialogAdapter</code>, <code>IInlineSearchAdapter</code></a>）を実行すれば、Hook が昇格して起動されているときに限り、管理者権限で実行されているエクスプローラー、Total Commander、ファイル ダイアログを読み取り操作できます。また、フック処理がクラッシュしてもメイン App には影響しません。</li></ul><h2 id="_2-共通コアライブラリ-lertaro-core" tabindex="-1">2. 共通コアライブラリ（<code>Lertaro.Core</code>） <a class="header-anchor" href="#_2-共通コアライブラリ-lertaro-core" aria-label="Permalink to “2. 共通コアライブラリ（Lertaro.Core）”">​</a></h2><p><code>Lertaro.Core</code> は、Service、App、Hook の各プロセスから共通して参照される基本ライブラリです。</p><ul><li><strong>独自 fzf あいまい一致エンジン（<code>Core/SearchIndex/Fzf/*</code>）</strong>：<code>fzf</code> アルゴリズムに基づく文字飛び一致、スコアリング、ハイライトマスク計算を実装。</li><li><strong>列指向インメモリインデックス（<code>Core/IndexV2/*</code>）</strong>：メモリマップト列指向スナップショットとインメモリ差分レイヤーにより、数億件のファイルからミリ秒未満で結果を抽出。</li><li><strong>バイナリ IPC 通信仕様</strong>：<code>SearchRequestMessage</code> などの標準バイナリプロトコルにより、プロセス間でゼロコピーに近い高速なシリアライズを実現。</li><li><strong>統合ログシステム（<code>Logger</code>）</strong>：<code>service.log</code>、<code>app.log</code>、<code>hook.log</code> にそれぞれ出力し、設定画面のログビューアーから統合的に閲覧可能。</li></ul><h2 id="_3-プラグインシステムのアーキテクチャ上の位置づけ" tabindex="-1">3. プラグインシステムのアーキテクチャ上の位置づけ <a class="header-anchor" href="#_3-プラグインシステムのアーキテクチャ上の位置づけ" aria-label="Permalink to “3. プラグインシステムのアーキテクチャ上の位置づけ”">​</a></h2><p>すべてのプラグインは <code>Lertaro.PluginSdk</code> をベースに構築され、<code>Lertaro.App</code> 起動時に動的ロードされます。</p><ul><li><strong>標準コンポーネント</strong>：プラグイン自身のコードは、それをロードしたプロセスと同じプロセス内で実行されます。通常は App ですが、Service もロードする 2 種類のコンポーネントについては次の項を参照してください。プラグイン自体がプロセス境界を越えることはないため、独自のディレクトリ インデックスが必要なプラグインは、ディスクを直接走査するのではなく <code>DirectoryIndexerService</code> を介して処理を依頼します。</li><li><strong>選択的な二重ロード</strong>：検索ソース、アクション、UI コンポーネントは App プロセス内でのみ動作します。ほかのプロセスにもロードされるのは次の 3 つです。ウィンドウおよびファイル ダイアログ アダプター（<code>IActivePathCollector</code>、<code>IFileDialogAdapter</code>、<code>IInlineSearchAdapter</code>）は、異なる整合レベルのウィンドウを自動化するため Hook プロセスに渡され、<code>IAliasProvider</code> と <code>ITranslationProvider</code> は <strong>Service</strong> にもロードされます（<code>ServicePluginLoader</code>）。インデクサーがエイリアスの行を構築し、UI に表示されるのと同じ文字起こしと命名を必要とするためです。</li></ul>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};